async function downloadFileFromUrl(url, fileName) {
  if (!url) return;
  const cleanName = fileName || "document.pdf";
  const toastId = import_sonner5.toast.loading(`Preparing download for ${cleanName}...`);
  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const blob = await response.blob();
    const blobUrl = window.URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = blobUrl;
    link.download = cleanName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setTimeout(() => window.URL.revokeObjectURL(blobUrl), 1e3);
    import_sonner5.toast.success("Download started!", { id: toastId });
  } catch (err) {
    console.warn("[downloadFileFromUrl] Fetch download failed, fallback to direct trigger:", err);
    import_sonner5.toast.dismiss(toastId);
    const link = document.createElement("a");
    link.href = url;
    link.download = cleanName;
    link.target = "_blank";
    link.rel = "noopener noreferrer";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }
}

